local GameConfig = require(script.Parent.Parent.Config.GameConfig)
local Ownership = {}
local function validPlayer(player)
 return typeof(player) == "Instance" and player:IsA("Player") and player.UserId > 0
end
function Ownership.IsOwner(player)
 if not validPlayer(player) then return false end
 if table.find(GameConfig.Owner.UserIds, player.UserId) then return true end
 return game.CreatorType == Enum.CreatorType.User and game.CreatorId == player.UserId
end
function Ownership.IsLeadDeveloper(player)
 if not validPlayer(player) then return false end
 local config = GameConfig.LeadDevelopers
 return config ~= nil and table.find(config.UserIds, player.UserId) ~= nil
end
function Ownership.HasOwnerPerks(player)
 return Ownership.IsOwner(player) or Ownership.IsLeadDeveloper(player)
end
function Ownership.CanUseTool(player, def)
 return def ~= nil and (not def.OwnerOnly or Ownership.HasOwnerPerks(player))
end
function Ownership.CanHavePet(player, def)
 return def ~= nil and (not def.OwnerOnly or Ownership.HasOwnerPerks(player))
end
return Ownership

