local DailyRewardConfig = {
	Name = "WRECKER DAILY",
	Cooldown = 72000,
	-- Visits resume after an absence; rewards keep their 20-hour cooldown.
	VipBonus = 0.5,
	Days = {
		{ Day = 1, Name = "CASH", Icon = "DailyCash", Rewards = { Cash = 1000 } },
		{ Day = 2, Name = "SCRAP", Icon = "DailyScrap", Rewards = { Scrap = 400 } },
		{ Day = 3, Name = "BOOST", Icon = "DailyBoost", Rewards = { Boost = { Id = "Cash2x", Seconds = 900 } } },
		{ Day = 4, Name = "CASH", Icon = "DailyCash", Rewards = { Cash = 5000 } },
		{ Day = 5, Name = "TOOL SKIN", Icon = "DailySkin", Rewards = { Skin = "Chrome", SkinFallback = { Scrap = 2500 } } },
		{ Day = 6, Name = "CHAOS CORES", Icon = "DailyCores", Rewards = { ChaosCores = 5 } },
		{ Day = 7, Name = "MEGA REWARD", Icon = "DailyMega", Rewards = { Cash = 25000, ChaosCores = 10, Boost = { Id = "Damage2x", Seconds = 1800 } } },
	},
}

function DailyRewardConfig.Status(data, timestamp)
 local reward=data.DailyReward or {}
 local last=tonumber(reward.LastClaim)or 0
 local elapsed=(timestamp or os.time())-last
 local claimable=last==0 or elapsed>=DailyRewardConfig.Cooldown
 return claimable,(tonumber(reward.Day)or 0)%#DailyRewardConfig.Days+1,math.max(DailyRewardConfig.Cooldown-elapsed,0)
end
return DailyRewardConfig

